/// `cx0`: the x0 core inside the box (kept in s7).: the x0 core inside the box (s7).
pub(crate) fn cx0_block(c: &mut Cpu) {
    let s3 = c.g[S3][0] as u32;
    c.cycles += 4;
    let t = !lt_fcc(c, 13, 15);
    c.g[S7][0] = 0;
    if !t {
        c.cycles += 5;
        load_f(c, 0, s3.wrapping_add(BOX_MAX));
        if lt_fcc(c, 16, 0) {
            c.g[S7][0] = 1;
        }
    }
}

