                scramble(c, &mut r);
                let desc = DATA + 0x100;
                c.g[A0][0] = DATA as u64;
                c.g[A1][0] = desc as u64;
                c.g[A2][0] = (DATA as u64 + 0x200) | ((r.next_u32() as u64) << 32);
                c.g[GP][0] = GAME_GP as u64;
