    /// `OverlapList_FindClosestContact`: no contact, one, and up to 64 with
    /// distance ties broken by object key, object-vs-world and surface key.
    #[test]
    fn overlap_list_find_closest_contact_matches() {
        install_fake_slots();
        check(
            ssx3_ee::s11::f_003342d0__generated,
            overlap_list_find_closest_contact,
            200,
            &|c, seed| {
                let mut r = Rng(0x0033_42d0 ^ (seed as u64) << 24);
                scramble(c, &mut r);
                c.pc = 0x0033_42d0;
                let list = DATA;
                let volume = DATA + 0x100;
                let vtable = DATA + 0x200;
                let out = DATA + 0x300;
                let template = DATA + 0x1_0000;
                let objects = DATA + 0x2_0000;
                let surfaces = DATA + 0x2_1000;
                c.g[A0][0] = sx(list);
                c.g[A1][0] = sx(volume);
                c.g[A2][0] = sx(out);
                c.g[A3][0] = r.next_u32() as u64;
                // Slot 3: `CollSegment_GetDiameter` (f0 = *(this + 0xa0)).
                c.bus.write32(volume + 0x50, vtable);
                c.bus.write16(vtable + 0x18, 0);
                c.bus.write32(vtable + 0x1c, 0x0034_0a10);
                let reference = [0.0f32, 1.0, 2.0, 0.5][r.next_u32() as usize % 4];
                c.bus.write32(volume + 0xa0, reference.to_bits());
                let count = match seed % 8 {
                    0 => 0,
                    1 => 1,
                    2 => 64,
                    _ => 2 + r.next_u32() % 20,
                };
                c.bus.write32(FCC_CTRL, FCC_MAGIC);
                c.bus.write32(FCC_CTRL + 4, count);
                c.bus.write32(FCC_CTRL + 8, template);
                for k in 0..3 {
                    c.bus.write32(objects + 0x100 * k + 0x78, r.next_u32() % 3);
                    c.bus
                        .write32(surfaces + 0x200 * k + 0x150, r.next_u32() % 3);
                }
                for i in 0..count {
                    let hit = template + 0x80 * i;
                    for w in 0..0x20 {
                        c.bus.write32(hit + 4 * w, r.next_u32());
                    }
                    let dist = [0.0f32, 1.0, 2.0, 3.0, -1.0, 1.5][r.next_u32() as usize % 6];
                    c.bus.write32(hit + 0x40, dist.to_bits());
                    let object = match r.next_u32() % 3 {
                        0 => 0,
                        _ => objects + 0x100 * (r.next_u32() % 3),
                    };
                    c.bus.write32(hit + 0x50, object);
                    c.bus
                        .write32(hit + 0x54, surfaces + 0x200 * (r.next_u32() % 3));
                }
            },
        );
    }

    /// Write vtable slot `off` = `{0, f}` (no `this` adjustment).
    fn slot4(c: &mut Cpu, vt: u32, off: u32, f: u32) {
        c.bus.write16(vt + off, 0);
        c.bus.write32(vt + off + 4, f);
    }

    /// OverlapList_FindNearestRail: lists of 0-4 objects of every type
    /// (rail modifier, flex rail, plain rail with flags passing or failing
    /// the mask, and non-rail types). The real callees take their short
    /// exits: the rail modifier's piece lookup finds no piece (its mask test
    /// reads flag 0), the flex rail's flags fail the mask, and the plain
    /// rail's bounds lie beyond the query box.
    #[test]
    fn overlap_list_find_nearest_rail_matches_2() {
        use crate::difftest::fakes::machine;
        use crate::difftest::{check, put_vec, DATA, GAME_GP};
        const LIST: u32 = DATA + 0x1000;
        const POS: u32 = DATA + 0x2000;
        const OUT: u32 = DATA + 0x2100;
        const OBJS: u32 = DATA + 0x4000;
        // The getter 0x2d1bd8 returns the word at gp+0x16c8: a table whose
        // piece array (+8) is empty, so the modifier finds no piece.
        const PIECES: u32 = DATA + 0x3000;
        check(
            ee::s11::f_00334680__generated,
            overlap_list_find_nearest_rail_2,
            300,
            &|c, seed| {
                let mut r = machine(c, seed, 0x3346_80, 0);
                c.pc = 0x0033_4680;
                c.bus.write32(GAME_GP + 0x16c8, PIECES);
                c.bus.write32(PIECES, PIECES + 0x10);
                c.bus.write32(PIECES + 0x10 + 8, PIECES + 0x40);
                for i in 0..0x100 {
                    c.bus.write32(PIECES + 0x40 + 4 * i, 0);
                }
                let count = if seed % 7 == 0 {
                    0
                } else {
                    1 + r.next_u32() % 4
                };
                c.bus.write32(LIST + 0x210, count);
                for i in 0..count {
                    let obj = OBJS + 0x200 * i;
                    let ty = r.next_u32() % 6; // 0, 4, 5: no rail
                    c.bus.write32(LIST + 0x214 + 4 * i, obj);
                    c.bus.write32(obj + 8, ty);
                    // Rail modifier / flex rail data.
                    let data = obj + 0x100;
                    c.bus.write32(obj + 0xc, data);
                    c.bus.write32(data + 0x30, r.next_u32()); // piece index
                    c.bus.write32(data + 0x24, 0x8000_0000); // flex flags
                                                             // Plain rail: instance flags, bounds beyond the box.
                    c.bus.write32(obj + 0x68, obj + 0x180);
                    let flags = if r.next_u32() % 2 == 0 { 0x10 } else { 0x4 };
                    c.bus.write32(obj + 0x180 + 0x1c, flags);
                    c.bus.write32(obj + 0x6c, 1000.0f32.to_bits());
                }
                put_vec(
                    c,
                    POS,
                    [4.0f32.to_bits(), 3.0f32.to_bits(), 2.0f32.to_bits(), 0],
                );
                c.g[A0][0] = sx(LIST);
                c.g[A1][0] = sx(POS);
                c.g[A2][0] = sx(OUT);
                c.g[A3][0] = sx(0x7fff_fff0 | (seed & 0xf)); // mask: 0x10 passes
                c.f[12] = 1.5f32.to_bits();
            },
        );
    }

    // ---- Collide_VolumeObject (0x334888) ----

    pub(crate) mod volume {
        const B: u32 = 0x00b0_0000;
        pub const QUERY: u32 = B;
        pub const QUERY_VT: u32 = B + 0x100;
        pub const NODE: u32 = B + 0x1000;
        pub const INST: u32 = B + 0x1400;
        pub const INST_VT: u32 = B + 0x1500;
        pub const TYPEREC: u32 = B + 0x2000;
        pub const SECTION: u32 = B + 0x2400;
        pub const TABLE: u32 = B + 0x2500;
        pub const LIST: u32 = B + 0x3000;
        pub const PARTS: u32 = B + 0x3100;
        pub const SHAPES: u32 = B + 0x3400;
        pub const MATRICES: u32 = B + 0x4000;
        pub const OUT: u32 = B + 0x8000;
        pub const WOBJ: u32 = B + 0x6000;
    }

    /// A query whose tests (+0x30/+0x38/+0x48) are real 0/1 functions (one
    /// contact at most per part) and whose load/close (+0x8/+0x10) are
    /// fakes; a node with or without an instance (own-collision, animated
    /// or single-matrix), collision type 0..4, 0..3 parts with bone or no
    /// bone (-1), with or without a shape; the world object (`gp+0x16c8`)
    /// whose section tables lead to empty meshes (`Collide_MeshLeafTriangles`
    /// returns at once).
    pub(crate) fn collide_volume_object_setup(c: &mut Cpu, seed: u32) {
        use volume::*;
        let mut r = machine(c, seed, 0x0033_4888, 8);
        let pick = |r: &mut Rng| if r.next_u32() % 3 == 0 { RET0 } else { RET1 };
        c.bus.write32(QUERY + 0x50, QUERY_VT);
        slot4(c, QUERY_VT, 0x8, FAKE);
        slot4(c, QUERY_VT, 0x10, FAKE + 0x10);
        for off in [0x30, 0x38, 0x48] {
            let f = pick(&mut r);
            slot4(c, QUERY_VT, off, f);
        }
        // Instance: own collision (+0x130), animated (+0xd0).
        c.bus
            .write32(NODE + 0xc, if seed % 4 == 0 { 0 } else { INST });
        c.bus.write32(INST + 0xc, INST_VT);
        slot4(c, INST_VT, 0x130, if seed % 5 == 1 { RET1 } else { RET0 });
        slot4(c, INST_VT, 0x138, FAKE + 0x20);
        let animated = pick(&mut r);
        slot4(c, INST_VT, 0xd0, animated);
        slot4(c, INST_VT, 0xe0, FAKE + 0x30);
        slot4(c, INST_VT, 0xc8, FAKE + 0x40);
        for i in 0..16 {
            c.bus.write32(NODE + 0x10 + 4 * i, r.f32(4.0));
        }
        // Collision type and per-part surface records (+0x1a: -1 or not).
        c.bus.write32(NODE + 0x88, TYPEREC);
        c.bus.write32(TYPEREC, r.next_u32() % 5);
        c.bus.write32(TYPEREC + 0xc, SECTION);
        for i in 0..8 {
            let h = if r.next_u32() & 1 == 0 {
                0xffff
            } else {
                r.next_u32() & 0x7fff
            };
            c.bus.write16(TYPEREC + 0x1a + 0xc * i, h as u16);
            c.bus.write16(TYPEREC + 0x16 + 0xc * i, r.next_u32() as u16);
        }
        // Section data -> table of (empty) meshes / sphere trees.
        c.bus.write32(SECTION + 0x8, TABLE);
        c.bus.write32(GAME_GP + 0x16c8, WOBJ);
        // Parts.
        c.bus.write32(NODE + 0x80, LIST);
        c.bus.write32(NODE + 0x84, r.f32(2.0));
        c.bus.write32(LIST + 4, r.next_u32() % 4);
        c.bus.write32(LIST + 8, PARTS);
        for i in 0..4 {
            let part = PARTS + 0x10 * i;
            let bone = if r.next_u32() % 3 == 0 {
                u32::MAX
            } else {
                r.next_u32() % 24
            };
            c.bus.write32(part, bone);
            let shape = SHAPES + 0x40 * i;
            c.bus
                .write32(part + 4, if r.next_u32() % 4 == 0 { 0 } else { shape });
            c.bus.write32(part + 0xc, MATRICES + 0x40 * i);
            fill(c, &mut r, shape, 0x10);
            for w in 0..16 {
                c.bus.write32(MATRICES + 0x40 * i + 4 * w, r.f32(4.0));
            }
        }
        c.g[A0][0] = QUERY as u64;
        c.g[A1][0] = NODE as u64;
        c.g[A2][0] = OUT as u64;
        c.g[A3][0] = 0x40;
        c.g[T0][0] = (r.next_u32() % 4) as u64;
        c.pc = 0x0033_4888;
    }

    /// Own-collision instances, rejected types, single and animated
    /// matrices, parts with and without a bone or shape, every query test
    /// result, contacts copied out; unwinds at the fake calls.
    #[test]
    fn collide_volume_object_matches() {
        covered(
            ee::s11::f_00334888__generated,
            collide_volume_object,
            240,
            &collide_volume_object_setup,
        );
    }

    pub(crate) fn gp_at_2(off: i32) -> u32 {
        GAME_GP.wrapping_add(off as u32)
    }

    /// Nash_CollideVolume: the query box is the point (1,1,1) and the
    /// classification margin is 0, so a level-0 cell at (0,0,0) is "inside"
    /// (collect), one at (1,1,1) is partly inside (recurse) and one at
    /// (5,5,5) is outside. Each of the eight cells gets a random kind and a
    /// tree or none; trees hold one instance, one object and empty subtrees
    /// (all callees are real and take their short paths).
    #[test]
    fn nash_collide_volume_matches() {
        check(
            ee::s11::f_00335d78__generated,
            nash_collide_volume,
            200,
            &|c, seed| {
                let mut r = Rng(0x9e37_79b9_7f4a_7c15 ^ (seed as u64) << 8 ^ 0x35d7);
                scramble(c, &mut r);
                c.pc = 0x0033_5d78;
                c.g[GP][0] = GAME_GP as u64;
                let belib = DATA + 0x3_0000;
                let world = DATA + 0x3_1000;
                c.bus.write32(gp_at_2(-0x1f04), belib);
                c.bus.write32(gp_at_2(-0x848), world);
                c.bus.write32(world + 0x84, world + 0x100);
                c.bus.write32(world + 0x100 + 0x7c, 0);
                // Classification margin (SpatialKey_ClassifyAABB) and the
                // recursion's 0.2 constants.
                c.bus.write32(gp_at_2(-0x2dfc), 0);
                for k in 0..16 {
                    c.bus.write32(gp_at_2(-0x2d10 + 4 * k), f_2(0.2));
                }

                let grid = DATA;
                let q = DATA + 0x400;
                for k in 0..4 {
                    c.bus.write32(
                        q + 0x20 + 4 * k,
                        if k < 3 { f_2(1.0) } else { r.next_u32() },
                    );
                    c.bus.write32(
                        q + 0x30 + 4 * k,
                        if k < 3 { f_2(1.0) } else { r.next_u32() },
                    );
                }
                c.bus.write32(grid + 0xa4, r.next_u32());
                // One instance (not collidable) and one object, shared.
                let inst = DATA + 0x3000;
                let obj = DATA + 0x3100;
                c.bus.write32(inst, 0);
                c.bus.write16(inst + 0xa, 0);
                c.bus.write32(obj, 0);
                c.bus.write32(obj + 0x88, 0);
                let empty = DATA + 0x3200; // an all-zero tree node
                for k in 0..8u32 {
                    let cell = grid + 0x14 * k;
                    let xyz = [0u32, 1, 5][(r.next_u32() % 3) as usize];
                    c.bus.write32(cell, 0);
                    for a in 1..4 {
                        c.bus.write32(cell + 4 * a, xyz);
                    }
                    let tree = DATA + 0x1000 + 0x100 * k;
                    let present = (seed + k) % 5 != 0;
                    c.bus.write32(cell + 0x10, if present { tree } else { 0 });
                    let bits = r.next_u32();
                    c.bus
                        .write32(tree + 0x24, if bits & 1 != 0 { inst } else { 0 });
                    c.bus
                        .write32(tree + 0x20, if bits & 2 != 0 { obj } else { 0 });
                    for i in 0..8 {
                        let child = bits >> (2 + i) & 1 != 0;
                        c.bus.write32(tree + 4 * i, if child { empty } else { 0 });
                    }
                }
                c.g[A0][0] = sx(grid);
                c.g[A1][0] = sx(q);
                c.g[A2][0] = sx(DATA + 0x5000);
                c.g[A3][0] = r.next_u32() as u64 % 8;
                c.g[T0][0] = r.next_u32() as u64;
            },
        );
    }

    use ssx3_ee_rt::Cpu;

    /// Nash_FindClosestContact over the real `Nash_CollideVolume`: eight
    /// level-0 cells at random places around a query volume (box around
    /// the origin), each tree holding a chain of up to four instances
    /// whose forward-difference entry makes the volume's (fake) triangle
    /// test run, so 0..n contacts with fake distances come back; the
    /// query's reference distance (virtual 0x18) is a fake too. Also
    /// checks that some seeds found contacts.
    #[test]
    fn nash_find_closest_contact_matches() {
        use crate::game::intersect::worldsphtree::tests::{
            put_cache, put_instance, put_volume, setup_machine, VT_VOL,
        };
        let f = |x: f32| x.to_bits();
        let setup = |c: &mut Cpu, seed: u32| {
            let mut r = setup_machine(c, seed, 0x0033_6850, 6);
            c.pc = 0x0033_6850;
            let (belib, world) = (DATA + 0x3_8000, DATA + 0x3_9000);
            c.bus.write32(GAME_GP - 0x1f04, belib);
            c.bus.write32(GAME_GP - 0x848, world);
            c.bus.write32(world + 0x84, world + 0x100);
            c.bus.write32(world + 0x100 + 0x7c, 0);
            c.bus.write32(GAME_GP - 0x2dfc, 0);
            for k in 0..16 {
                c.bus.write32(GAME_GP - 0x2d10 + 4 * k, f(0.2));
            }
            let (grid, q, cache, out) = (DATA, DATA + 0x400, DATA + 0xc00, DATA + 0x6000);
            put_volume(c, &mut r, q);
            c.bus.write16(VT_VOL + 0x18, 0);
            c.bus.write32(VT_VOL + 0x1c, FAKE + 0x70);
            put_cache(c, cache);
            c.bus.write32(grid + 0xa4, cache);
            // Instance chains (inst+0 = next).
            let mut chains = Vec::new();
            for k in 0..4u32 {
                let count = (seed + k) % 5;
                let mut next = 0;
                for i in 0..count {
                    let inst = DATA + 0x8000 + 0x800 * k + 0x200 * i;
                    put_instance(c, &mut r, inst, seed + i + k);
                    c.bus.write32(inst, next);
                    next = inst;
                }
                chains.push(next);
            }
            for k in 0..8u32 {
                let cell = grid + 0x14 * k;
                let xyz = [0u32, 1, 5, u32::MAX][(r.next_u32() % 4) as usize];
                c.bus.write32(cell, 0);
                for a in 1..4 {
                    c.bus.write32(cell + 4 * a, xyz);
                }
                let tree = DATA + 0x1000 + 0x100 * k;
                for i in 0..10 {
                    c.bus.write32(tree + 4 * i, 0);
                }
                c.bus
                    .write32(tree + 0x24, chains[(r.next_u32() % 4) as usize]);
                c.bus
                    .write32(cell + 0x10, if (seed + k) % 6 != 0 { tree } else { 0 });
            }
            c.g[A0][0] = sx(grid);
            c.g[A1][0] = sx(q);
            c.g[A2][0] = sx(out);
            c.g[A3][0] = r.next_u32() as u64 % 8;
        };
        check(
            ee::s11::f_00336850__generated,
            nash_find_closest_contact,
            200,
            &setup,
        );
        let found = (0..60)
            .filter(|&seed| {
                let mut c = crate::difftest::fresh();
                setup(&mut *c, seed);
                crate::difftest::run_generated(&mut *c, ee::s11::f_00336850__generated);
                c.f[0] != 0xbf80_0000
            })
            .count();
        assert!(found >= 6, "contacts found in only {found} of 60 seeds");
    }

    /// AnimTeeter_v15: positive and negative gain, steps over and under
    /// the limit (both signs), both end stops with bounce or stop, and the
    /// end script firing or not (the script manager has no script table,
    /// as the AnimObject_FireEndScript test builds it).
    #[test]
    fn anim_teeter_v15_matches() {
        use super::teeter::*;
        check(
            ee::s11::f_00342358__generated,
            anim_teeter_v15,
            300,
            &|c, seed| {
                let mut r = machine(c, seed, 0x342358, 0);
                c.pc = 0x0034_2358;
                let s = DATA + 0x100;
                let obj = s + POS;
                let list = DATA + 0x1000;
                let man = DATA + 0x2000;
                let world = DATA + 0x3000;
                for off in (0..0x60).step_by(4) {
                    c.bus.write32(s + off, r.f32(2.0));
                }
                c.bus.write32(s + MIN, (-1.0f32).to_bits());
                c.bus.write32(s + MAX, 1.0f32.to_bits());
                c.bus.write32(s + MAX_STEP, r.f32(0.5) & 0x7fff_ffff);
                c.bus.write32(s + BOUNCE, r.f32(1.0));
                c.bus.write32(s + POS, r.f32(1.5));
                c.bus
                    .write32(s + VEL, r.f32(if seed % 2 == 0 { 0.2 } else { 30.0 }));
                c.bus.write16(s + FLAGS, r.next_u32() as u16);
                // World frame time.
                c.bus.write32(GAME_GP - 0x848, world);
                c.bus.write32(
                    world + 0x14,
                    if seed % 3 == 0 {
                        r.f32(1.0)
                    } else {
                        (1.0f32 / 60.0).to_bits()
                    },
                );
                c.bus.write32(GAME_GP - GP_STOP_SPEED_MIN, 0.1f32.to_bits());
                c.bus.write32(GAME_GP - GP_STOP_SPEED_MAX, 0.1f32.to_bits());
                // AnimObject_FireEndScript: `list->head == obj + 0x14` decides.
                c.bus.write32(GAME_GP + 0xce8, man);
                c.bus.write32(man + 0x28c, 0);
                c.bus.write32(list + 0x78, 0);
                c.bus.write32(list + 0x88, 0);
                c.bus.write32(obj + 0x2c, list);
                c.bus.write32(
                    list + 0xc,
                    if seed % 4 < 2 { obj + 0x14 } else { obj + 0x40 },
                );
                c.g[A0][0] = sx(s);
            },
        );
    }

    /// `OverlapList_GatherType2` against the generated body, with the real
    /// callees (`SpatialKey_ClassifyAABB`, `Cell_GatherType2Subtree`,
    /// `Cell_GatherType2Recursive`) on short paths. Every seed gives each of
    /// the eight top-level cells a random fate: no tree, box inside the cell
    /// (append the root's type-2 list, gather its children whole), partly
    /// overlapping (recurse) or disjoint (skip).
    #[test]
    fn overlap_list_gather_type2_matches() {
        use crate::difftest::{check, scramble, Rng, DATA, GAME_GP};
        use gather_type2_list as list;
        let fbits = |x: f32| x.to_bits();
        check(
            ee::s11::f_00331450__generated,
            overlap_list_gather_type2,
            200,
            &|c, seed| {
                let mut r = Rng(0x9e37_79b9_7f4a_7c15 ^ (seed as u64) << 8 ^ 0x1450);
                scramble(c, &mut r);
                c.pc = 0x0033_1450;
                c.g[GP][0] = GAME_GP as u64;
                let gp_at = |off: i32| (GAME_GP as i32 + off) as u32;
                // The BELibrary dummy and the world (callees' globals).
                let belib = DATA + 0x3_0000;
                let world = DATA + 0x3_1000;
                c.bus.write32(gp_at(-0x1f04), belib);
                c.bus.write32(gp_at(-0x848), world);
                c.bus.write32(world + 0x84, world + 0x100);
                c.bus.write32(world + 0x100 + 0x7c, 0);
                // SpatialKey_ClassifyAABB's cell margin.
                c.bus.write32(gp_at(-0x2dfc), fbits(0.25));

                let this = DATA;
                let grid = DATA + 0x1000;
                let bx = DATA + 0x1200;
                // Leaf children: one with no list, one with a one-item list.
                let leaf = DATA + 0x3000;
                let leaf_item = DATA + 0x3100;
                let leaf_list = DATA + 0x3200;
                c.bus.write32(leaf_item + list::NODE_TYPE2, leaf_list);
                c.bus.write32(leaf_list, 0);
                // Stale count and cached counts (reset / invalidated).
                c.bus.write32(this + list::ITEM_COUNT, r.next_u32());
                c.bus.write32(this + list::NTRIS, r.next_u32());
                c.bus.write32(this + list::COUNT, r.next_u32());
                c.bus.write32(this + list::GRID, grid);
                c.bus.write32(grid + list::GRID_STAMP, r.next_u32());
                // The query box (as in `overlap_list_gather_all_matches`): a
                // level-0 cell at the origin classifies 0 ("within"), a
                // level-1 cell at the origin 2 (partly), one at x = 100 1.
                for (k, v) in [1.25f32, 1.25, 0.0].into_iter().enumerate() {
                    c.bus.write32(bx + 4 * k as u32, fbits(v));
                    c.bus.write32(bx + 0x10 + 4 * k as u32, fbits(0.5));
                }
                for i in 0..8u32 {
                    let cell = grid + list::CELL_SIZE * i;
                    let root = DATA + 0x2000 + 0x100 * i;
                    let (level, x) = match r.next_u32() % 4 {
                        0 => (0, 0),
                        1 => (1, 0),
                        _ => (0, 100),
                    };
                    c.bus.write32(cell, level);
                    c.bus.write32(cell + 4, x);
                    c.bus.write32(cell + 8, 0);
                    c.bus.write32(cell + 0xc, 0);
                    let present = r.next_u32() % 5 != 0;
                    c.bus
                        .write32(cell + list::CELL_ROOT, if present { root } else { 0 });
                    // The root: 0..3 type-2 items; random leaf children.
                    for off in [0x20u32, 0x24] {
                        c.bus.write32(root + off, 0);
                    }
                    let mut next = 0;
                    for j in 0..r.next_u32() % 4 {
                        let item = DATA + 0x7000 + 0x10 * (4 * i + j);
                        c.bus.write32(item, next);
                        next = item;
                    }
                    c.bus.write32(root + list::NODE_TYPE2, next);
                    for k in 0..8u32 {
                        let child = match r.next_u32() % 4 {
                            0 => leaf,
                            1 => leaf_item,
                            _ => 0,
                        };
                        c.bus.write32(root + 4 * k, child);
                    }
                }
                c.g[A0][0] = sx(this);
                c.g[A1][0] = sx(bx);
            },
        );
    }

    /// `AnimObject_ctor` with the real constructor chain
    /// (`AnimObject_BaseCtor` -> `ModObj_ctor` -> `WorldObj_ctor` on the
    /// `world_obj_ctor_matches` fixture: process lists, world -> focus
    /// manager; a node whose info has no entries, so `AllocNodeInfo` and
    /// `AnimObject_v52` take their short paths and the instance stays 0),
    /// the pool allocator, and definitions with min/max/value negative or
    /// not, random value or not, speed spread or not, both directions; the
    /// frame rate at `gp+0x2a74 -> +0x10`.
    #[test]
    fn anim_object_ctor_matches() {
        use crate::difftest::fill;
        use crate::game::fe::feasyncfile::tests::{heap_init_4, pool_allocator_7};
        const ANIM: u32 = DATA + 0x800;
        const NODE: u32 = DATA + 0x200;
        const INFO: u32 = DATA + 0x600;
        const DEF: u32 = DATA + 0x700;
        const RATE: u32 = DATA + 0x780;
        const PROCS: u32 = DATA + 0x1000;
        const TAILS: u32 = DATA + 0x1400;
        const WORLD: u32 = DATA + 0x2000;
        const FOCUS: u32 = DATA + 0x3000;
        check(
            ee::s11::f_00341aa0__generated,
            anim_object_ctor,
            120,
            &|c, seed| {
                let mut r = machine(c, seed, 0x34_1aa0, 0);
                pool_allocator_7(c);
                heap_init_4(c);
                let w = |c: &mut Cpu, a: u32, v: u32| c.bus.write32(a, v);
                fill(c, &mut r, ANIM, 0x20);
                fill(c, &mut r, NODE, 0x10);
                let flags = r.next_u32();
                w(
                    c,
                    NODE + 0x8,
                    if seed % 4 == 0 {
                        flags | 0x100
                    } else {
                        flags & !0x100
                    },
                );
                w(c, NODE + 0x80, INFO);
                // Node info: no entries; the max used for a negative max.
                w(c, INFO + 0x4, 0);
                w(c, INFO + 0x8, 0);
                w(c, INFO + 0x14, r.f32(10.0));
                // Process lists and the world -> focus manager chain.
                w(c, GAME_GP + 0x2898 + 4, PROCS);
                for i in 0..4 {
                    w(c, PROCS + 0x44 * i, r.next_u32());
                    w(c, PROCS + 0x44 * i + 8, TAILS + 0x40 * i);
                    w(c, PROCS + 0x44 * i + 0x28, TAILS + 0x40 * i + 0x20);
                }
                fill(c, &mut r, 0x0044_aff0, 0x20);
                w(c, GAME_GP - 0x848, WORLD);
                w(c, WORLD + 0x84, WORLD + 0x100);
                w(c, WORLD + 0x100 + 0xc, WORLD + 0x200);
                w(c, WORLD + 0x200 + 0xa4, FOCUS);
                w(
                    c,
                    FOCUS + 0xd4,
                    if seed % 3 == 0 { 0 } else { r.next_u32() },
                );
                w(c, FOCUS + 0xd8, r.next_u32() % 8);
                // Scales (1/30 s) and the frame rate.
                for off in [0x2b94u32, 0x2b90, 0x2b8c, 0x2b88, 0x2b84] {
                    w(c, GAME_GP - off, (1.0f32 / 30.0).to_bits());
                }
                w(c, GAME_GP + 0x2a74, RATE);
                w(c, RATE + 0x10, if seed % 5 == 0 { 30 } else { 60 });
                // The definition.
                let signed = |r: &mut Rng, neg: bool| {
                    let v = r.f32(20.0) & 0x7fff_ffff;
                    if neg {
                        v | 0x8000_0000
                    } else {
                        v
                    }
                };
                w(c, DEF + 0x4, r.next_u32());
                w(
                    c,
                    DEF + 0x8,
                    if seed % 3 == 1 { 1 } else { r.next_u32() % 3 },
                );
                w(c, DEF + 0xc, signed(&mut r, seed % 4 == 1));
                w(c, DEF + 0x10, signed(&mut r, seed % 5 == 2));
                w(c, DEF + 0x14, r.f32(30.0));
                w(c, DEF + 0x18, if seed % 2 == 0 { 0 } else { r.f32(10.0) });
                w(c, DEF + 0x1c, signed(&mut r, seed % 6 == 3));
                w(c, DEF + 0x20, if seed % 7 == 4 { 1 } else { 0 });
                w(c, DEF + 0x24, if seed % 3 == 0 { 1 } else { 0 });
                let kind = match (seed / 4) % 6 {
                    0 => 6,
                    1 => 0x10,
                    2 => 0x16,
                    _ => r.next_u32() % 0x20,
                };
                c.g[A0][0] = sx(ANIM);
                c.g[A1][0] = sx(seed % 4);
                c.g[A2][0] = sx(kind);
                c.g[A3][0] = sx(NODE);
                c.g[T0][0] = sx(DEF);
                c.pc = 0x0034_1aa0;
            },
        );
    }

    /// A stream whose vtable has a fake in every slot (AnimObject_BaseSave,
    /// ModObj_Save and WorldObj_Save write through several of them).
    pub(crate) fn oc308_all_fake_stream(
        c: &mut Cpu,
        r: &mut crate::difftest::Rng,
        stream: u32,
        vt: u32,
    ) {
        c.bus.write32(stream, vt);
        for off in (0..0x340).step_by(8) {
            let delta = ((r.next_u32() as i16 as i32 % 64) & !3) as u16;
            c.bus.write16(vt + off, delta);
            c.bus.write32(vt + off + 4, FAKE + 2 * off);
        }
    }

    /// The base save runs for real (its stream writes are fakes; no modifier
    /// block to save), then the teeter's own write; any call may unwind.
    #[test]
    fn anim_teeter_save_matches() {
        covered(
            ee::s11::f_00342718__generated,
            anim_teeter_save,
            200,
            &|c, seed| {
                let mut r = machine(c, seed, 0x34_2718, 8);
                let self_ = DATA;
                crate::difftest::fill(c, &mut r, self_, 0x40);
                let base = self_ + ANIM_TEETER_ANIM_OBJECT;
                // ModObj (base + 0x14): no modifier block; WorldObj fields zero.
                c.bus.write32(base + 0x30, 0);
                c.bus.write32(base + 0x4c, 0);
                let stream = DATA + 0x1000;
                oc308_all_fake_stream(c, &mut r, stream, DATA + 0x2000);
                c.g[A0][0] = sx(self_);
                c.g[A1][0] = sx(stream);
                c.pc = 0x0034_2718;
            },
        );
    }

    /// The base destructor runs for real on a heap object (empty ModObj, an
    /// optional cache block, no nodes); `flags & 1` frees the object.
    #[test]
    fn anim_object_dtor_matches() {
        use crate::difftest::GAME_GP;
        use crate::game::bx::cubicspline::tests::oc238_run;
        crate::difftest::check(
            ee::s11::f_00341cf0__generated,
            anim_object_dtor,
            200,
            &|c, seed| {
                let mut r = machine(c, seed, 0x34_1cf0, 0);
                // The game heap over test memory, pools off.
                c.bus.write32(GAME_GP + 0xdd8, 0);
                oc238_run(
                    c,
                    0x0031_ff60,
                    ee::s10::f_0031ff60,
                    &[0x004f_f250, (DATA + 0x40000) as u64, 0x40000],
                );
                let alloc = |c: &mut Cpu, size: u64| -> u32 {
                    oc238_run(c, 0x0031_9e48, ee::s10::f_00319e48, &[size, 0]) as u32
                };
                let me = alloc(c, 0x80);
                for i in 0..0x20 {
                    c.bus.write32(me + 4 * i, 0);
                }
                crate::difftest::fill(c, &mut r, me, 0x7);
                let base = me + ANIM_OBJECT_DTOR_BASE;
                c.bus.write16(base + 0x14 + 0x10, (r.next_u32() % 8) as u16);
                let cache = if seed % 3 == 0 { 0 } else { alloc(c, 0x20) };
                c.bus.write32(base + 0x44, cache);
                c.g[A0][0] = sx(me);
                c.g[A1][0] = (r.next_u32() & 0xff) as u64;
                c.pc = 0x0034_1cf0;
            },
        );
    }

    /// `Debounce_ctor_2` runs the real `ModObj` constructor chain (its
    /// `WorldObj` and sync-process fixtures mirror `mod_obj_ctor_matches`):
    /// definitions with mode 0, 1 and >=2, node flags with the focus bit and
    /// with or without both low bits set, and an empty `a4` source for the
    /// take-over.
    #[test]
    fn debounce_ctor_2_matches() {
        use crate::difftest::fakes::machine;
        use crate::difftest::{check, fill, DATA, GAME_GP};
        const SELF: u32 = DATA + 0x100;
        const NODE: u32 = DATA + 0x200;
        const DEF: u32 = DATA + 0x300;
        const PROCS: u32 = DATA + 0x1000;
        const TAILS: u32 = DATA + 0x1400;
        const WORLD: u32 = DATA + 0x2000;
        const FOCUS: u32 = DATA + 0x3000;
        const SCALE: u32 = DATA + 0x4000;
        check(
            ee::s11::f_00342c08__generated,
            debounce_ctor_2,
            240,
            &|c, seed| {
                let mut r = machine(c, seed, 0x34_2c08, 0);
                c.pc = 0x0034_2c08;
                let w = |c: &mut Cpu, a: u32, v: u32| c.bus.write32(a, v);
                fill(c, &mut r, SELF, 0x10);
                fill(c, &mut r, NODE, 0x10);
                let flags = (r.next_u32() & !0xf)
                    | if seed % 4 == 0 { 0x100 } else { 0 }
                    | if seed % 2 == 0 { 3 } else { (seed / 8) % 3 };
                w(c, NODE + DEBOUNCE_NODE_FLAGS, flags);
                w(c, GAME_GP + 0x2898 + 4, PROCS);
                for i in 0..4 {
                    w(c, PROCS + 0x44 * i, r.next_u32());
                    w(c, PROCS + 0x44 * i + 8, TAILS + 0x40 * i);
                    w(c, PROCS + 0x44 * i + 0x28, TAILS + 0x40 * i + 0x20);
                }
                fill(c, &mut r, 0x0044_aff0, 0x20);
                // World -> game -> race -> focus manager.
                w(c, GAME_GP - 0x848, WORLD);
                w(c, WORLD + 0x84, WORLD + 0x100);
                w(c, WORLD + 0x100 + 0xc, WORLD + 0x200);
                w(c, WORLD + 0x200 + 0xa4, FOCUS);
                w(
                    c,
                    FOCUS + 0xd4,
                    if seed % 3 == 0 { 0 } else { r.next_u32() },
                );
                w(c, FOCUS + 0xd8, r.next_u32() % 8);
                // The definition: a time, the +8 word and the mode.
                w(c, DEF + DEBOUNCE_DEF_TIME, r.f32(8.0));
                w(c, DEF + DEBOUNCE_DEF_F08, r.next_u32());
                w(c, DEF + DEBOUNCE_DEF_MODE, ((seed / 4) % 3) as u32);
                // The tick-rate scale pointer and its value.
                w(c, DEBOUNCE_RATE_SCALE, SCALE);
                w(
                    c,
                    SCALE + 0x10,
                    [0, 1, 2, 60, u32::MAX][(seed % 5) as usize],
                );
                // The process-list index, as in `mod_obj_ctor_matches`: it
                // reaches `ProcessList_Add` as a byte offset into PROCS.
                let list = (seed % 4) as u64;
                c.g[A0][0] = sx(SELF);
                c.g[A1][0] = list;
                c.g[A2][0] = sx(NODE);
                c.g[A3][0] = sx(DEF);
                c.g[T0][0] = 0; // no source node: the take-over takes its empty path
            },
        );
    }

